import React from 'react';
import '../styles/MeetingSection.css';

const MeetingSection = () => {
    return (
        <section className="meeting-section">
            <div className="meeting-container">
                <img src={`${process.env.PUBLIC_URL}/imgg/Rectangle 275 (1).png`} alt="Запис на зустріч" className="meeting-bg" />
                <div className="meeting-content">
                    <h2>Запишіться на консультацію з дизайнером</h2>
                    <div className="meeting-divider"></div>
                    <p>Отримайте професійну пораду, індивідуальний проєкт і рішення, що ідеально пасують до вашого простору. Онлайн або в шоурумі — як зручно вам.</p>
                    <ul className="meeting-list">
                        <li>Індивідуальний підхід</li>
                        <li>Поради щодо стилю, меблів, зонування</li>
                        <li>Візуалізації або приклади рішень</li>
                    </ul>
                </div>
                <a href="#" className="meeting-btn">Записатись на зустріч</a>
            </div>
        </section>
    );
};

export default MeetingSection;
